slides.codeSnippet:
// PercentPipe
{{ 0.85 | percent }}              // '85%'
{{ 0.85 | percent:'2.1-2' }}      // '85.00%'

// SlicePipe (array or string)
{{ items | slice:0:3 }}            // first 3 items
{{ 'Hello World' | slice:0:5 }}    // 'Hello'

// Component
user = { name: 'Alex', roles: ['admin', 'editor'] };

// Template
<pre>{{ user | json }}</pre>
/* Output:
{
  "name": "Alex",
  "roles": [
    "admin",
    "editor"
  ]
}
*/
